SELECT person_id
  FROM person
 WHERE external_id = #{externalId}

SELECT A.*, B.* FROM ( SELECT tt1.rnum no, tt1.person_id, tt1.external_id, tt1.name_ko, tt1.name_org, tt1.profile_image_url, TO_CHAR(tt1.created_dt, 'YYYY-MM-DD HH24:MI:SS') created_dt, TO_CHAR(tt1.updated_dt, 'YYYY-MM-DD HH24:MI:SS') updated_dt FROM ( SELECT ROWNUM rnum, t1.* FROM ( SELECT * FROM person
ORDER BY created_dt DESC, person_id ASC ) t1 WHERE ROWNUM <= (#{pageSize} * (#{pageNo} - 1) + #{pageSize}) ) tt1 WHERE rnum >= (#{pageSize} * (#{pageNo} - 1) + 1) ) A CROSS JOIN ( SELECT COUNT(*) total_cnt FROM person
) B
